recipes.code:
{
  "inputs": [
    {
      "id": "peil-api-key",
      "type": "promptString",
      "description": "Scoped API key from Peil under Settings -> Developer settings (Pro).",
      "password": true
    }
  ],
  "servers": {
    "peil": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "peil-mcp@0.1.3"
      ],
      "env": {
        "PEIL_API_KEY": "${input:peil-api-key}",
        "PEIL_API_URL": "https://api.peil.app/api/v1"
      }
    }
  }
}
